-- US-020 review fixes. Owner decision D1 (2026-11-20): checkout dedupe reuses an open order only for the
-- SAME buyer, the same phone AND name AND e-mail after normalisation: orders.buyer_key (SHA-256, 32 bytes,
-- @ebooktrivia/core buyerKey), required on every order, and orders_dedupe_idx on (LP, phone, buyer_key,
-- created_at). Security review P2: captcha.ip48_cap (the Cap routes per IPv6 /48, on top of the /64) joins
-- APP_SETTING_BOUNDS.
ALTER TABLE "app_settings" DROP CONSTRAINT "app_settings_bounds_check";--> statement-breakpoint
DROP INDEX "orders_dedupe_idx";--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "buyer_key" "bytea";--> statement-breakpoint
-- Orders written before this migration get a key no checkout can produce (a hash of their own id), so
-- they are never deduped against; new orders must carry the checkout's key.
UPDATE "orders" SET "buyer_key" = sha256(convert_to('ebooktrivia/buyer-key/legacy|' || "id"::text, 'UTF8')) WHERE "buyer_key" IS NULL;--> statement-breakpoint
ALTER TABLE "orders" ALTER COLUMN "buyer_key" SET NOT NULL;--> statement-breakpoint
CREATE INDEX "orders_dedupe_idx" ON "orders" USING btree ("landing_page_id","buyer_phone","buyer_key","created_at");--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_buyer_key_check" CHECK (octet_length("orders"."buyer_key") = 32);--> statement-breakpoint
ALTER TABLE "app_settings" ADD CONSTRAINT "app_settings_bounds_check" CHECK (CASE WHEN "app_settings"."key" NOT IN ('otp.code_ttl_seconds', 'otp.max_attempts', 'otp.phone_cap', 'otp.phone_window_seconds', 'otp.ip_cap', 'otp.ip_window_seconds', 'otp.cooldown_seconds', 'orders.expiry_seconds', 'orders.sales_close_buffer_minutes', 'checkout.ip_cap', 'checkout.ip_window_seconds', 'checkout.phone_cap', 'checkout.phone_window_seconds', 'checkout.lp_cap', 'checkout.lp_window_seconds', 'captcha.ip_cap', 'captcha.ip_window_seconds', 'captcha.ip48_cap') THEN true WHEN jsonb_typeof("app_settings"."value") <> 'number' THEN false ELSE CASE "app_settings"."key" WHEN 'otp.code_ttl_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 900 WHEN 'otp.max_attempts' THEN (value #>> '{}')::numeric BETWEEN 1 AND 5 WHEN 'otp.phone_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 10 WHEN 'otp.phone_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 3600 AND 86400 WHEN 'otp.ip_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 100 WHEN 'otp.ip_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 600 AND 86400 WHEN 'otp.cooldown_seconds' THEN (value #>> '{}')::numeric BETWEEN 15 AND 600 WHEN 'orders.expiry_seconds' THEN (value #>> '{}')::numeric BETWEEN 900 AND 86400 WHEN 'orders.sales_close_buffer_minutes' THEN (value #>> '{}')::numeric BETWEEN 5 AND 1440 WHEN 'checkout.ip_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 1000 WHEN 'checkout.ip_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 86400 WHEN 'checkout.phone_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 100 WHEN 'checkout.phone_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 86400 WHEN 'checkout.lp_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 100000 WHEN 'checkout.lp_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 86400 WHEN 'captcha.ip_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 1000 WHEN 'captcha.ip_window_seconds' THEN (value #>> '{}')::numeric BETWEEN 60 AND 86400 WHEN 'captcha.ip48_cap' THEN (value #>> '{}')::numeric BETWEEN 1 AND 100000 END END);